"""Versioned, additive domain schema. Existing data is backed up before migration."""

SCHEMA = """
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS organization_members(user_id TEXT PRIMARY KEY REFERENCES users(id), org_id TEXT NOT NULL REFERENCES organizations(id), role TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS member_invites(hash TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), email TEXT NOT NULL, role TEXT NOT NULL, expires REAL NOT NULL, consumed_at TEXT);
CREATE TABLE IF NOT EXISTS auth_tokens(hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL, expires REAL NOT NULL, consumed_at TEXT);
CREATE TABLE IF NOT EXISTS consent_events(id TEXT PRIMARY KEY, candidate_id TEXT NOT NULL REFERENCES candidates(id), kind TEXT NOT NULL, granted INTEGER NOT NULL, policy_version TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS consent_latest ON consent_events(candidate_id,kind,created_at);
CREATE TABLE IF NOT EXISTS company_profiles(org_id TEXT PRIMARY KEY REFERENCES organizations(id), payload TEXT NOT NULL, verification TEXT NOT NULL DEFAULT 'pending', version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS assessment_sessions(id TEXT PRIMARY KEY, candidate_id TEXT NOT NULL REFERENCES candidates(id), specialization TEXT NOT NULL, grade TEXT NOT NULL, mode TEXT NOT NULL, status TEXT NOT NULL, payload TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, expires REAL NOT NULL, completed_at TEXT);
CREATE INDEX IF NOT EXISTS assessment_owner ON assessment_sessions(candidate_id,created_at);
CREATE TABLE IF NOT EXISTS assessment_answers(session_id TEXT NOT NULL REFERENCES assessment_sessions(id), item_id TEXT NOT NULL, answer TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, saved_at TEXT NOT NULL, PRIMARY KEY(session_id,item_id));
CREATE TABLE IF NOT EXISTS grade_certifications(id TEXT PRIMARY KEY, candidate_id TEXT NOT NULL REFERENCES candidates(id), specialization TEXT NOT NULL, grade TEXT NOT NULL, score REAL NOT NULL, session_id TEXT REFERENCES assessment_sessions(id), status TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS certification_owner ON grade_certifications(candidate_id,specialization,active);
CREATE TABLE IF NOT EXISTS assessment_appeals(id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES assessment_sessions(id), candidate_id TEXT NOT NULL REFERENCES candidates(id), message TEXT NOT NULL, state TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assessment_reviews(id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES assessment_sessions(id), reviewer_id TEXT NOT NULL REFERENCES users(id), item_id TEXT, score REAL, rationale TEXT NOT NULL, appeal_id TEXT REFERENCES assessment_appeals(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS employer_needs(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), payload TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', version INTEGER NOT NULL DEFAULT 1, expires REAL NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS search_sessions(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), actor_id TEXT NOT NULL REFERENCES users(id), need_id TEXT NOT NULL REFERENCES employer_needs(id), payload TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS need_passports(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), candidate_id TEXT NOT NULL REFERENCES candidates(id), need_id TEXT NOT NULL REFERENCES employer_needs(id), snapshot TEXT NOT NULL, fingerprint TEXT NOT NULL, integrity_sha256 TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS invitations(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), candidate_id TEXT NOT NULL REFERENCES candidates(id), need_id TEXT NOT NULL REFERENCES employer_needs(id), sender_id TEXT NOT NULL REFERENCES users(id), payload TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, history TEXT NOT NULL, created_at TEXT NOT NULL, request_key TEXT NOT NULL, UNIQUE(sender_id,request_key));
CREATE TABLE IF NOT EXISTS contact_grants(id TEXT PRIMARY KEY, candidate_id TEXT NOT NULL REFERENCES candidates(id), org_id TEXT NOT NULL REFERENCES organizations(id), invitation_id TEXT REFERENCES invitations(id), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, revoked_at TEXT);
CREATE INDEX IF NOT EXISTS contact_access ON contact_grants(candidate_id,org_id,active);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL, entity_id TEXT, payload TEXT NOT NULL, read_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS external_identities(id TEXT PRIMARY KEY, candidate_id TEXT NOT NULL REFERENCES candidates(id), provider TEXT NOT NULL, issuer TEXT NOT NULL, subject TEXT NOT NULL, participant_id TEXT NOT NULL, status TEXT NOT NULL, method TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL, revoked_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS external_identity_confirmed ON external_identities(provider,issuer,subject) WHERE status IN ('verified','demo');
CREATE TABLE IF NOT EXISTS oidc_states(hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), payload TEXT NOT NULL, expires REAL NOT NULL, consumed_at TEXT);
CREATE TABLE IF NOT EXISTS identity_proofs(hash TEXT PRIMARY KEY, candidate_id TEXT NOT NULL REFERENCES candidates(id), participant_id TEXT NOT NULL, expires REAL NOT NULL, consumed_at TEXT);
CREATE TABLE IF NOT EXISTS moderation_cases(id TEXT PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES users(id), org_id TEXT NOT NULL REFERENCES organizations(id), need_id TEXT REFERENCES employer_needs(id), kind TEXT NOT NULL, message TEXT NOT NULL, state TEXT NOT NULL, resolution TEXT, created_at TEXT NOT NULL, resolved_at TEXT);
CREATE TABLE IF NOT EXISTS employer_blocks(candidate_id TEXT NOT NULL REFERENCES candidates(id), org_id TEXT NOT NULL REFERENCES organizations(id), created_at TEXT NOT NULL, PRIMARY KEY(candidate_id,org_id));
CREATE TABLE IF NOT EXISTS ats_connections(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), provider TEXT NOT NULL, account_id TEXT NOT NULL, encrypted_token TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(org_id,provider,account_id));
CREATE TABLE IF NOT EXISTS ats_links(connection_id TEXT NOT NULL REFERENCES ats_connections(id), entity_type TEXT NOT NULL, local_id TEXT NOT NULL, external_id TEXT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(connection_id,entity_type,local_id), UNIQUE(connection_id,entity_type,external_id));
CREATE TABLE IF NOT EXISTS integration_events(id TEXT PRIMARY KEY, connection_id TEXT NOT NULL REFERENCES ats_connections(id), direction TEXT NOT NULL, external_key TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, error TEXT, created_at TEXT NOT NULL, completed_at TEXT, UNIQUE(connection_id,direction,external_key));
CREATE TABLE IF NOT EXISTS recruitment_stages(invitation_id TEXT PRIMARY KEY REFERENCES invitations(id), connection_id TEXT NOT NULL REFERENCES ats_connections(id), external_id TEXT NOT NULL, stage TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS applications(id TEXT PRIMARY KEY, candidate_id TEXT NOT NULL REFERENCES candidates(id), org_id TEXT NOT NULL REFERENCES organizations(id), vacancy_id TEXT NOT NULL REFERENCES vacancies(id), status TEXT NOT NULL, payload TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(candidate_id,vacancy_id));
CREATE INDEX IF NOT EXISTS applications_org ON applications(org_id,created_at);
CREATE TABLE IF NOT EXISTS regular_cases(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), state TEXT NOT NULL, payload TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS case_subscriptions(candidate_id TEXT NOT NULL REFERENCES candidates(id), case_id TEXT NOT NULL REFERENCES regular_cases(id), enabled INTEGER NOT NULL, next_due REAL NOT NULL, PRIMARY KEY(candidate_id,case_id));
CREATE TABLE IF NOT EXISTS case_attempts(id TEXT PRIMARY KEY, candidate_id TEXT NOT NULL REFERENCES candidates(id), case_id TEXT NOT NULL REFERENCES regular_cases(id), state TEXT NOT NULL, payload TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, reviewed_at TEXT);
CREATE TABLE IF NOT EXISTS pilot_observations(id TEXT PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assessment_passports(id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES assessment_sessions(id), candidate_id TEXT NOT NULL REFERENCES candidates(id), revision INTEGER NOT NULL, snapshot TEXT NOT NULL, integrity_sha256 TEXT NOT NULL, published INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, UNIQUE(session_id,revision));
CREATE INDEX IF NOT EXISTS assessment_passports_owner ON assessment_passports(candidate_id,created_at);
"""
